from scripts import diag_p106b_repair_role_course as c
from collections import Counter
from datetime import datetime,timezone
import json
r,rows,_=c.read_course();tok=c._tokenizer();result={}
for arm in c.ARMS:
 seen=set();total=Counter();unique=Counter();by_language={l:Counter() for l in ('ko','en')}
 for epoch in range(4):
  for row in rows[arm+'_train'+str(epoch)]:
   rec,_=c.factory.encode(row,tok);key=c.conversation_signature(row['messages']);lang=row['meta']['language']
   total.update(rows=1,x_tokens=rec.x_tokens,assistant_targets=rec.targets)
   by_language[lang].update(rows=1,x_tokens=rec.x_tokens,assistant_targets=rec.targets)
   if key not in seen:
    seen.add(key);unique.update(serialized_conversations=1,serialized_x_tokens=rec.x_tokens)
 assert total['x_tokens']==r['expected_exposures'][arm]['x_tokens'] and total['assistant_targets']==r['expected_exposures'][arm]['assistant_targets']
 result[arm]=dict(total_draws=dict(total),distinct_serialized_conversations=dict(unique),language_draws={k:dict(v) for k,v in by_language.items()})
print(json.dumps(dict(schema='P106B_SERIALIZED_EXPOSURE_POSTHOC_V1',created_at=datetime.now(timezone.utc).isoformat(),corpus_sha256=c.training.data.digest(c.CORPUS/'report.json'),arms=result,definition='Deduplicate canonical messages with original producer SHA; sum actual factory.encode x once per distinct serialization. Not semantic facts or novel pretraining exposure.',masking='Total assistant targets uses actual factory encoder, including protected wrong-first mask',native='Separate1769472 processed x per arm; novel native text/substring overlap NOT_ESTABLISHED',model_loaded=False,cuda=False,optimizer=0),ensure_ascii=False))
